INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('Python Code Generation Guidelines','code_generation','Python','Write readable Python with clear names and small functions. Validate external inputs, handle expected exceptions, avoid hard-coded secrets, and keep business logic separate from UI and API code.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO documents (title,content,source) VALUES ('Python Code Generation Guidelines','Write readable Python with clear names and small functions. Validate external inputs, handle expected exceptions, avoid hard-coded secrets, and keep business logic separate from UI and API code.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('Python Debugging Checklist','debugging','Python','Read the full traceback and identify the exception and failing line. Check imports, spelling, file paths, active virtual environment, installed packages, and environment variables. Reproduce the smallest failing case, fix the root cause, then rerun the failing test.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO documents (title,content,source) VALUES ('Python Debugging Checklist','Read the full traceback and identify the exception and failing line. Check imports, spelling, file paths, active virtual environment, installed packages, and environment variables. Reproduce the smallest failing case, fix the root cause, then rerun the failing test.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('Python Unit Testing','testing','Python','Use pytest. Name test files test_*.py and test functions test_*. Cover normal inputs, edge cases, invalid inputs, and expected exceptions. Keep tests independent and deterministic. Mock external APIs when appropriate. A passing test confirms only the behavior exercised.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO documents (title,content,source) VALUES ('Python Unit Testing','Use pytest. Name test files test_*.py and test functions test_*. Cover normal inputs, edge cases, invalid inputs, and expected exceptions. Keep tests independent and deterministic. Mock external APIs when appropriate. A passing test confirms only the behavior exercised.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('Java Code Generation and Debugging','code_generation','Java','Use classes and methods with clear responsibilities. Match public class names to filenames. Check imports, packages, access modifiers, and data types. Compile with javac and fix the first meaningful compiler error before follow-on errors.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO documents (title,content,source) VALUES ('Java Code Generation and Debugging','Use classes and methods with clear responsibilities. Match public class names to filenames. Check imports, packages, access modifiers, and data types. Compile with javac and fix the first meaningful compiler error before follow-on errors.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('JavaScript Code Generation and Debugging','code_generation','JavaScript','Use const by default and let when reassignment is needed. Handle rejected promises and validate API data. Use node --check for syntax checks, then run behavior tests. Browser-only APIs may not be available in Node.js.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO documents (title,content,source) VALUES ('JavaScript Code Generation and Debugging','Use const by default and let when reassignment is needed. Handle rejected promises and validate API data. Use node --check for syntax checks, then run behavior tests. Browser-only APIs may not be available in Node.js.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('SQL Query Writing and Validation','sql','SQL','Prefer explicit column names. Use parameterized queries for user-supplied values; do not concatenate untrusted input into SQL. Check joins, grouping, NULL behavior, and table names. Carefully check WHERE clauses before UPDATE or DELETE.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO documents (title,content,source) VALUES ('SQL Query Writing and Validation','Prefer explicit column names. Use parameterized queries for user-supplied values; do not concatenate untrusted input into SQL. Check joins, grouping, NULL behavior, and table names. Carefully check WHERE clauses before UPDATE or DELETE.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('Code Review Checklist','review','General','Review correctness, readability, security, error handling, maintainability, and tests. Look for duplicated logic, large functions, hard-coded credentials, unsafe input handling, and unclear names. Explain findings and their impact. Do not claim code was tested unless it was actually run.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO documents (title,content,source) VALUES ('Code Review Checklist','Review correctness, readability, security, error handling, maintainability, and tests. Look for duplicated logic, large functions, hard-coded credentials, unsafe input handling, and unclear names. Explain findings and their impact. Do not claim code was tested unless it was actually run.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('Code Optimization Principles','optimization','General','Optimize after identifying a bottleneck. Preserve behavior and readability. Consider algorithmic complexity, repeated work, database indexes, and avoidable network calls. Measure before and after and add tests to ensure behavior has not changed.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO documents (title,content,source) VALUES ('Code Optimization Principles','Optimize after identifying a bottleneck. Preserve behavior and readability. Consider algorithmic complexity, repeated work, database indexes, and avoidable network calls. Measure before and after and add tests to ensure behavior has not changed.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('RAG Retrieval and Grounded Answers','rag','General','RAG retrieves relevant passages from a knowledge source and supplies them as context to a language model. Split documents into meaningful chunks and preserve source metadata. If the source does not support an answer, say the information is insufficient. For a question about one uploaded file, retrieve only that file.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO documents (title,content,source) VALUES ('RAG Retrieval and Grounded Answers','RAG retrieves relevant passages from a knowledge source and supplies them as context to a language model. Split documents into meaningful chunks and preserve source metadata. If the source does not support an answer, say the information is insufficient. For a question about one uploaded file, retrieve only that file.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('Safe Coding Agent Behavior','agent_rules','General','State assumptions and limitations. Do not invent APIs or test results. Protect API keys and secrets. Take care with destructive file operations. Distinguish generated code from code that has actually been run.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO documents (title,content,source) VALUES ('Safe Coding Agent Behavior','State assumptions and limitations. Do not invent APIs or test results. Protect API keys and secrets. Take care with destructive file operations. Distinguish generated code from code that has actually been run.','AI_Coding_Agent_RAG_Knowledge_Base.pdf');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('Python Type Hints and Dataclasses','code_generation','Python','Add type hints to public functions and class attributes. Use dataclasses for simple data containers, with frozen=True when values should not change. Run mypy or pyright to catch type mismatches before running the code.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO documents (title,content,source) VALUES ('Python Type Hints and Dataclasses','Add type hints to public functions and class attributes. Use dataclasses for simple data containers, with frozen=True when values should not change. Run mypy or pyright to catch type mismatches before running the code.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('Python Exception Handling','code_generation','Python','Catch only the exceptions you expect, and name them specifically. Never use a bare except that silently swallows errors. Raise custom exceptions with clear messages and chain original causes with ''raise ... from err''.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO documents (title,content,source) VALUES ('Python Exception Handling','Catch only the exceptions you expect, and name them specifically. Never use a bare except that silently swallows errors. Raise custom exceptions with clear messages and chain original causes with ''raise ... from err''.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('Python Virtual Environments and Dependencies','debugging','Python','Create a project virtual environment and pin dependencies in requirements.txt or pyproject.toml. Confirm the interpreter with ''which python'' before installing packages. Many import errors come from installing into the wrong environment.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO documents (title,content,source) VALUES ('Python Virtual Environments and Dependencies','Create a project virtual environment and pin dependencies in requirements.txt or pyproject.toml. Confirm the interpreter with ''which python'' before installing packages. Many import errors come from installing into the wrong environment.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('Python API Input Validation','code_generation','Python','Validate request bodies at the API boundary before they reach business logic. Pydantic models or explicit checks should reject missing fields, wrong types, and out-of-range values with a clear 400-level error.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO documents (title,content,source) VALUES ('Python API Input Validation','Validate request bodies at the API boundary before they reach business logic. Pydantic models or explicit checks should reject missing fields, wrong types, and out-of-range values with a clear 400-level error.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('Java Unit Testing with JUnit','testing','Java','Write JUnit 5 tests in a parallel src/test directory with the same package structure. Use assertEquals and assertThrows for expected results and exceptions. Keep each test focused on one behavior and avoid shared mutable state.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO documents (title,content,source) VALUES ('Java Unit Testing with JUnit','Write JUnit 5 tests in a parallel src/test directory with the same package structure. Use assertEquals and assertThrows for expected results and exceptions. Keep each test focused on one behavior and avoid shared mutable state.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('Java Exception Handling','code_generation','Java','Catch specific exception types rather than Exception or Throwable. Use try-with-resources for files, streams, and database connections so they close automatically. Include the failing input in error messages without exposing secrets.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO documents (title,content,source) VALUES ('Java Exception Handling','Catch specific exception types rather than Exception or Throwable. Use try-with-resources for files, streams, and database connections so they close automatically. Include the failing input in error messages without exposing secrets.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('JavaScript Async and Await Patterns','code_generation','JavaScript','Use async and await for sequential asynchronous steps and wrap them in try and catch. Use Promise.all for independent requests that can run in parallel. Remember that an unawaited promise can fail silently.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO documents (title,content,source) VALUES ('JavaScript Async and Await Patterns','Use async and await for sequential asynchronous steps and wrap them in try and catch. Use Promise.all for independent requests that can run in parallel. Remember that an unawaited promise can fail silently.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('JavaScript Debugging in Node.js','debugging','JavaScript','Run the script with node --inspect or add console.log at the failing boundary to confirm the actual values. Check for undefined properties, wrong module paths, and missing await keywords. Read the stack trace from the first project file listed.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO documents (title,content,source) VALUES ('JavaScript Debugging in Node.js','Run the script with node --inspect or add console.log at the failing boundary to confirm the actual values. Check for undefined properties, wrong module paths, and missing await keywords. Read the stack trace from the first project file listed.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('SQL Indexing Basics','optimization','SQL','Add indexes to columns used frequently in WHERE, JOIN, and ORDER BY clauses. Indexes speed reads but slow writes and use storage, so avoid indexing every column. Use EXPLAIN QUERY PLAN in SQLite to confirm an index is actually used.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO documents (title,content,source) VALUES ('SQL Indexing Basics','Add indexes to columns used frequently in WHERE, JOIN, and ORDER BY clauses. Indexes speed reads but slow writes and use storage, so avoid indexing every column. Use EXPLAIN QUERY PLAN in SQLite to confirm an index is actually used.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('SQL Transactions and Safe Updates','sql','SQL','Wrap related changes in a transaction so they succeed or fail together. Run a SELECT with the same WHERE clause before an UPDATE or DELETE to confirm which rows will change. Test destructive statements on a copy of the data first.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO documents (title,content,source) VALUES ('SQL Transactions and Safe Updates','Wrap related changes in a transaction so they succeed or fail together. Run a SELECT with the same WHERE clause before an UPDATE or DELETE to confirm which rows will change. Test destructive statements on a copy of the data first.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('Git Commit and Branch Hygiene','workflow','General','Keep each commit focused on one logical change with a short imperative message. Work on feature branches and review diffs before committing. Never commit credentials, local environment files, or generated build output.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO documents (title,content,source) VALUES ('Git Commit and Branch Hygiene','Keep each commit focused on one logical change with a short imperative message. Work on feature branches and review diffs before committing. Never commit credentials, local environment files, or generated build output.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('Secrets Management','security','General','Store API keys and passwords in environment variables or a secrets manager, never in source code. Add secret files to .gitignore and rotate any key that was ever committed. Mask secrets in logs and error output.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO documents (title,content,source) VALUES ('Secrets Management','Store API keys and passwords in environment variables or a secrets manager, never in source code. Add secret files to .gitignore and rotate any key that was ever committed. Mask secrets in logs and error output.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('REST API Error Responses','code_generation','General','Return consistent error bodies with a status code, a stable error code, and a readable message. Use 400 for invalid input, 401 or 403 for authentication and permission problems, and 404 for missing resources. Do not expose stack traces to clients.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO documents (title,content,source) VALUES ('REST API Error Responses','Return consistent error bodies with a status code, a stable error code, and a readable message. Use 400 for invalid input, 401 or 403 for authentication and permission problems, and 404 for missing resources. Do not expose stack traces to clients.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('RAG Chunking Strategies','rag','General','Split documents at natural boundaries such as headings, paragraphs, or table rows rather than at fixed character counts alone. Keep a small overlap between chunks so context is not lost. Store the title, source file, and position with every chunk.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO documents (title,content,source) VALUES ('RAG Chunking Strategies','Split documents at natural boundaries such as headings, paragraphs, or table rows rather than at fixed character counts alone. Keep a small overlap between chunks so context is not lost. Store the title, source file, and position with every chunk.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('Ingesting Excel and Word Files for RAG','rag','General','Convert each spreadsheet row or table into readable text that names its columns, for example ''Product: Widget, Price: 12.50''. Keep sheet name and row number as metadata. For Word files, preserve heading hierarchy so each chunk can be traced back to its section.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO documents (title,content,source) VALUES ('Ingesting Excel and Word Files for RAG','Convert each spreadsheet row or table into readable text that names its columns, for example ''Product: Widget, Price: 12.50''. Keep sheet name and row number as metadata. For Word files, preserve heading hierarchy so each chunk can be traced back to its section.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('Technical Documentation Writing','documentation','General','Begin each document with its purpose and audience. Use short sections with descriptive headings and include a working example. State prerequisites, known limitations, and the date or version the instructions apply to.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO documents (title,content,source) VALUES ('Technical Documentation Writing','Begin each document with its purpose and audience. Use short sections with descriptive headings and include a working example. State prerequisites, known limitations, and the date or version the instructions apply to.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('Logging Best Practices','review','General','Log events at appropriate levels: DEBUG for detail, INFO for normal milestones, WARNING for recoverable problems, and ERROR for failures. Include identifiers that help trace a request, but never log passwords, tokens, or personal data.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO documents (title,content,source) VALUES ('Logging Best Practices','Log events at appropriate levels: DEBUG for detail, INFO for normal milestones, WARNING for recoverable problems, and ERROR for failures. Include identifiers that help trace a request, but never log passwords, tokens, or personal data.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO knowledge_documents (title,category,language,content,source) VALUES ('Regular Expression Caution','code_generation','General','Keep regular expressions simple and test them against both matching and non-matching examples. Nested quantifiers can cause catastrophic backtracking on long input. For structured formats such as JSON or HTML, use a real parser instead.','AI_Coding_Agent_Extended_KB.docx');
INSERT INTO documents (title,content,source) VALUES ('Regular Expression Caution','Keep regular expressions simple and test them against both matching and non-matching examples. Nested quantifiers can cause catastrophic backtracking on long input. For structured formats such as JSON or HTML, use a real parser instead.','AI_Coding_Agent_Extended_KB.docx');
